//! Product images generated by `scripts/gen_images.py` into `data/images/`,
//! pre-resized by `scripts/gen_variants.py` into `data/images/variants/`.
//!
//! `asset!` needs a path known at compile time, so every file is declared
//! here once and a product picks one at runtime by category and ID, following
//! the script's rule: `{category_slug}-{(id % VARIANTS) + 1}`. The path only
//! has to be a `const &str`, so `concat!` inside `macro_rules!` spells out the
//! 96 declarations from one line per category.

use topcoat::asset::{Asset, asset};

use crate::catalog::Product;

/// Images generated per category.
pub const VARIANTS: usize = 3;

/// Pixel size of every original (square), used for `width`/`height`.
pub const IMAGE_SIZE: u32 = 1600;

/// Widths of the pre-resized WebP files. Keep in sync with
/// `scripts/gen_variants.py` and the `photo!` macro below.
pub const WIDTHS: [u32; 4] = [320, 640, 960, 1600];

/// Index into `WIDTHS` of the file used for `src`, for browsers that ignore
/// `srcset`.
const FALLBACK: usize = 1;

/// One original's resized files, in `WIDTHS` order. The widths are repeated
/// as literals because `concat!` cannot read a `const`.
macro_rules! photo {
    ($slug:literal, $n:literal) => {
        photo!($slug, $n, ["320", "640", "960", "1600"])
    };
    ($slug:literal, $n:literal, [$($width:literal),*]) => {
        [$(asset!(concat!("../../data/images/variants/", $slug, "-", $n, "-", $width, ".webp"))),*]
    };
}

/// A category's images, in variant order.
macro_rules! category {
    ($slug:literal) => {
        (
            $slug,
            [photo!($slug, "1"), photo!($slug, "2"), photo!($slug, "3")],
        )
    };
}

type Photo = [Asset; WIDTHS.len()];

const IMAGES: [(&str, [Photo; VARIANTS]); 8] = [
    category!("audio"),
    category!("displays"),
    category!("peripherals"),
    category!("storage"),
    category!("networking"),
    category!("cameras"),
    category!("wearables"),
    category!("smart-home"),
];

/// A product's image: one file per width in `WIDTHS`.
#[derive(Clone, Copy)]
pub struct ProductImage(&'static Photo);

impl ProductImage {
    /// The file for `src`.
    pub fn fallback(self) -> Asset {
        self.0[FALLBACK]
    }

    /// Every file with its width, for `srcset`.
    pub fn widths(self) -> impl Iterator<Item = (Asset, u32)> {
        self.0.iter().copied().zip(WIDTHS)
    }
}

/// The image for `product`, or `None` for a category without images.
pub fn product_image(product: &Product) -> Option<ProductImage> {
    let (_, variants) = IMAGES
        .iter()
        .find(|(slug, _)| *slug == product.category_slug)?;
    Some(ProductImage(&variants[product.id as usize % VARIANTS]))
}

/// Every declared file with the name the generator gives it.
#[cfg(test)]
fn declared_files() -> impl Iterator<Item = (Asset, String)> {
    IMAGES.iter().flat_map(|(slug, variants)| {
        variants.iter().enumerate().flat_map(move |(index, photo)| {
            photo
                .iter()
                .zip(WIDTHS)
                .map(move |(asset, width)| (*asset, format!("{slug}-{}-{width}.webp", index + 1)))
        })
    })
}

/// Resolves the product images, plus `extra` assets named by file, to
/// placeholder URLs, so views that render them work in tests without a
/// bundle from `topcoat asset bundle`.
#[cfg(test)]
pub fn test_asset_config(extra: &[(Asset, &str)]) -> topcoat::asset::AssetConfig {
    use topcoat::asset::{AssetConfig, MANIFEST_VERSION, Manifest, ManifestEntry};

    let entry = |asset: &Asset, file: String| ManifestEntry {
        id: asset.id(),
        file,
        hash: String::new(),
        content_type: String::new(),
    };
    let assets = declared_files()
        .map(|(asset, file)| entry(&asset, file))
        .chain(
            extra
                .iter()
                .map(|(asset, file)| entry(asset, (*file).to_owned())),
        )
        .collect();
    AssetConfig::hosted_at(
        "https://assets.test",
        Manifest {
            version: MANIFEST_VERSION,
            assets,
        },
    )
}

#[cfg(test)]
mod tests {
    use std::{collections::BTreeSet, path::Path};

    use super::*;
    use crate::catalog::Catalog;

    #[test]
    fn every_category_has_images() {
        let catalog = Catalog::load();
        for category in catalog.categories() {
            assert!(
                IMAGES.iter().any(|(slug, _)| *slug == category.slug),
                "no images for {}",
                category.slug
            );
        }
    }

    fn files_with_extension(dir: &str, extension: &str) -> BTreeSet<String> {
        std::fs::read_dir(Path::new(env!("CARGO_MANIFEST_DIR")).join(dir))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().into_string().unwrap())
            .filter(|name| {
                Path::new(name)
                    .extension()
                    .is_some_and(|ext| ext.eq_ignore_ascii_case(extension))
            })
            .collect()
    }

    /// Every original has one resized file per width, and the table lists
    /// exactly the files `gen_variants.py` wrote.
    #[test]
    fn table_matches_generated_files() {
        let originals = files_with_extension("../data/images", "jpg");
        let expected: BTreeSet<String> = originals
            .iter()
            .flat_map(|name| {
                let stem = name.trim_end_matches(".jpg").to_owned();
                WIDTHS.map(|width| format!("{stem}-{width}.webp"))
            })
            .collect();
        let declared: BTreeSet<String> = declared_files().map(|(_, file)| file).collect();
        assert_eq!(declared, expected);
        assert_eq!(
            files_with_extension("../data/images/variants", "webp"),
            expected
        );
    }

    /// `srcset` advertises each file's width, so the files must really have
    /// it. Reads the width from the lossy WebP (`VP8 `) frame header.
    #[test]
    fn variant_files_have_the_declared_width() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../data/images/variants");
        for (_, file) in declared_files() {
            let bytes = std::fs::read(dir.join(&file)).unwrap();
            assert_eq!(&bytes[12..16], b"VP8 ", "{file} is not a lossy WebP");
            let width = u32::from(u16::from_le_bytes([bytes[26], bytes[27]]) & 0x3fff);
            let declared: u32 = file
                .trim_end_matches(".webp")
                .rsplit('-')
                .next()
                .unwrap()
                .parse()
                .unwrap();
            assert_eq!(width, declared, "{file}");
        }
    }

    #[test]
    fn products_pick_a_variant_by_id() {
        let catalog = Catalog::load();
        let config = test_asset_config(&[]);
        let product = catalog.get(1).unwrap();
        let image = product_image(product).unwrap();
        let stem = format!("{}-{}", product.category_slug, 1 % VARIANTS + 1);
        let url = config.resolve(image.fallback());
        assert!(url.ends_with(&format!("{stem}-640.webp")), "{url}");
        let widths: Vec<_> = image
            .widths()
            .map(|(asset, width)| (config.resolve(asset), width))
            .collect();
        assert_eq!(widths.len(), WIDTHS.len());
        for (url, width) in widths {
            assert!(url.ends_with(&format!("{stem}-{width}.webp")), "{url}");
        }
    }
}
